# Schedule Validation and Feasibility Checking

## Overview
A valid production schedule must satisfy multiple constraints. This skill covers comprehensive validation techniques.

## Core Validation Functions

### 1. Check Machine Conflicts

```python
def validate_no_machine_conflicts(schedule):
    """
    Verify that no machine processes multiple operations simultaneously.
    Returns: (is_valid, error_messages)
    """
    machine_timeline = {}

    for op in schedule:
        machine = op['machine']
        start = op['start']
        end = op['end']

        if machine not in machine_timeline:
            machine_timeline[machine] = []

        # Check for overlaps with existing operations
        for existing_start, existing_end, existing_op in machine_timeline[machine]:
            # Check if [start, end) overlaps with [existing_start, existing_end)
            if start < existing_end and end > existing_start:
                return False, f"Machine {machine} conflict: Job {op['job']} Op {op['op']} [{start}, {end}) overlaps with Job {existing_op['job']} Op {existing_op['op']} [{existing_start}, {existing_end})"

        machine_timeline[machine].append((start, end, op))

    return True, ""
```

### 2. Check Precedence Constraints

```python
def validate_precedence(schedule):
    """
    Verify that operations within each job are executed in order.
    Returns: (is_valid, error_messages)
    """
    job_operations = {}

    # Group operations by job
    for op in schedule:
        job_id = op['job']
        if job_id not in job_operations:
            job_operations[job_id] = []
        job_operations[job_id].append(op)

    # Check each job's operations
    for job_id, ops in job_operations.items():
        # Sort by operation index
        ops_sorted = sorted(ops, key=lambda x: x['op'])

        # Check that end time of op[i] <= start time of op[i+1]
        for i in range(len(ops_sorted) - 1):
            if ops_sorted[i]['end'] > ops_sorted[i + 1]['start']:
                return False, f"Job {job_id}: Op {ops_sorted[i]['op']} ends at {ops_sorted[i]['end']} but Op {ops_sorted[i+1]['op']} starts at {ops_sorted[i+1]['start']}"

    return True, ""
```

### 3. Check Downtime Violations

```python
def validate_no_downtime_violations(schedule, downtimes):
    """
    Verify that no operation overlaps with machine downtime.
    Returns: (is_valid, violation_count, error_messages)
    """
    violations = 0
    errors = []

    for op in schedule:
        machine = op['machine']
        start = op['start']
        end = op['end']

        for dt in downtimes:
            if dt['machine'] != machine:
                continue

            # Check for overlap
            if start < dt['end'] and end > dt['start']:
                violations += 1
                errors.append(
                    f"Job {op['job']} Op {op['op']} on Machine {machine} "
                    f"[{start}, {end}) conflicts with downtime [{dt['start']}, {dt['end']})"
                )

    is_valid = violations == 0
    return is_valid, violations, "; ".join(errors)
```

### 4. Check Duration Consistency

```python
def validate_durations(schedule):
    """
    Verify that end - start = duration for all operations.
    Returns: (is_valid, error_messages)
    """
    for op in schedule:
        expected_dur = op['end'] - op['start']
        if expected_dur != op['dur']:
            return False, f"Job {op['job']} Op {op['op']}: duration mismatch (end-start={expected_dur}, dur={op['dur']})"

    return True, ""
```

### 5. Comprehensive Validation

```python
def validate_schedule(schedule, downtimes, jobs=None):
    """
    Perform comprehensive validation of a schedule.

    Returns:
        dict with keys: 'valid', 'errors', 'makespan', 'downtime_violations'
    """
    errors = []

    # 1. Check machine conflicts
    valid, error = validate_no_machine_conflicts(schedule)
    if not valid:
        errors.append(f"Machine conflict: {error}")

    # 2. Check precedence
    valid, error = validate_precedence(schedule)
    if not valid:
        errors.append(f"Precedence violation: {error}")

    # 3. Check durations
    valid, error = validate_durations(schedule)
    if not valid:
        errors.append(f"Duration error: {error}")

    # 4. Check downtime violations
    valid, violation_count, error = validate_no_downtime_violations(schedule, downtimes)
    if not valid:
        errors.append(f"Downtime violations ({violation_count}): {error}")
    else:
        violation_count = 0

    # 5. Calculate makespan
    makespan = max(op['end'] for op in schedule) if schedule else 0

    # 6. Verify machine/duration matches job definition (if provided)
    if jobs:
        for op in schedule:
            job_id = op['job']
            op_idx = op['op']
            machine = op['machine']
            duration = op['dur']

            if job_id in jobs and op_idx < len(jobs[job_id]):
                alternatives = jobs[job_id][op_idx]
                valid_assignment = any(
                    m == machine and d == duration
                    for m, d in alternatives
                )
                if not valid_assignment:
                    errors.append(
                        f"Job {job_id} Op {op_idx}: "
                        f"Invalid machine/duration ({machine}, {duration})"
                    )

    return {
        'valid': len(errors) == 0,
        'errors': errors,
        'makespan': makespan,
        'downtime_violations': violation_count
    }
```

## Policy Validation

```python
def validate_policy_constraints(schedule, policy, baseline_schedule, baseline_makespan):
    """
    Validate policy constraints including freeze, change budget, and guards.
    """
    errors = []

    if not policy:
        return {'valid': True, 'errors': []}

    # 1. Check freeze policy
    if policy.get('freeze', {}).get('enabled', False):
        freeze_until = policy['freeze']['freeze_until']
        lock_fields = policy['freeze']['lock_fields']

        baseline_dict = {(op['job'], op['op']): op for op in baseline_schedule}

        for op in schedule:
            key = (op['job'], op['op'])
            if key in baseline_dict:
                baseline_op = baseline_dict[key]
                if baseline_op['start'] < freeze_until:
                    for field in lock_fields:
                        if op[field] != baseline_op[field]:
                            errors.append(
                                f"Freeze violation: Job {op['job']} Op {op['op']} "
                                f"field '{field}' changed from {baseline_op[field]} to {op[field]}"
                            )

    # 2. Check change budget
    if 'change_budget' in policy:
        baseline_dict = {(op['job'], op['op']): op for op in baseline_schedule}

        machine_changes = 0
        total_start_shift = 0

        for op in schedule:
            key = (op['job'], op['op'])
            if key in baseline_dict:
                baseline_op = baseline_dict[key]
                if op['machine'] != baseline_op['machine']:
                    machine_changes += 1
                total_start_shift += abs(op['start'] - baseline_op['start'])

        max_machine_changes = policy['change_budget'].get('max_machine_changes', float('inf'))
        max_start_shift = policy['change_budget'].get('max_total_start_shift_L1', float('inf'))

        if machine_changes > max_machine_changes:
            errors.append(
                f"Change budget: {machine_changes} machine changes exceeds limit of {max_machine_changes}"
            )

        if total_start_shift > max_start_shift:
            errors.append(
                f"Change budget: total start shift {total_start_shift} exceeds limit of {max_start_shift}"
            )

    # 3. Check makespan guard
    if 'guards' in policy:
        makespan = max(op['end'] for op in schedule) if schedule else 0
        max_ratio = policy['guards'].get('max_makespan_ratio', float('inf'))

        if makespan > baseline_makespan * max_ratio:
            errors.append(
                f"Makespan guard: {makespan} exceeds {baseline_makespan * max_ratio} "
                f"(baseline {baseline_makespan} * {max_ratio})"
            )

    return {
        'valid': len(errors) == 0,
        'errors': errors
    }
```

