#!/usr/bin/env python3
"""
Production Scheduling Solver
Solves job shop scheduling with downtime and policy constraints.
"""

import json
import pandas as pd
from typing import Dict, List, Tuple


def parse_instance(filename: str) -> Dict[int, List[List[Tuple[int, int]]]]:
    """
    Parse JSSP instance file.
    Returns: jobs dictionary with structure:
    {
        job_id: [
            [(machine1, duration1), (machine2, duration2), ...],  # op 0 alternatives
            [(machine1, duration1), ...],  # op 1 alternatives
        ]
    }
    """
    jobs = {}
    with open(filename, 'r') as f:
        lines = f.readlines()

    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if not line or '→' not in line:
            i += 1
            continue

        parts = line.split('→')
        job_id = int(parts[0])
        num_ops = int(parts[1])

        jobs[job_id] = []

        # Read operations for this job
        for op_idx in range(num_ops):
            i += 1
            if i >= len(lines):
                break

            op_line = lines[i].strip()
            if not op_line:
                continue

            if '→' in op_line:
                op_parts = op_line.split('→')[1].split()
            else:
                op_parts = op_line.split()

            if not op_parts:
                continue

            num_alternatives = int(op_parts[0])
            alternatives = []

            for alt_idx in range(num_alternatives):
                machine = int(op_parts[1 + alt_idx * 2])
                duration = int(op_parts[2 + alt_idx * 2])
                alternatives.append((machine, duration))

            jobs[job_id].append(alternatives)

        i += 1

    return jobs


def load_downtime_windows(filename: str) -> List[Dict]:
    """Load machine downtime windows from CSV."""
    df = pd.read_csv(filename)
    downtimes = []
    for _, row in df.iterrows():
        downtimes.append({
            'machine': int(row['machine']),
            'start': int(row['start']),
            'end': int(row['end']),
            'reason': row.get('reason', '')
        })
    return downtimes


def load_policy(filename: str) -> Dict:
    """Load policy constraints from JSON file."""
    with open(filename, 'r') as f:
        return json.load(f)


def load_baseline(filename: str) -> Dict:
    """Load baseline schedule from JSON file."""
    with open(filename, 'r') as f:
        return json.load(f)


def conflicts_with_downtime(machine: int, start: int, end: int, downtimes: List[Dict]) -> bool:
    """Check if an operation conflicts with any downtime window."""
    for dt in downtimes:
        if dt['machine'] != machine:
            continue
        if start < dt['end'] and end > dt['start']:
            return True
    return False


def earliest_available_time(machine: int, duration: int, machine_schedule: Dict,
                            downtimes: List[Dict], after: int = 0) -> int:
    """Find the earliest time a machine can start an operation of given duration."""
    busy_periods = sorted(machine_schedule.get(machine, []), key=lambda x: x[0])

    candidate_start = after

    for start, end in busy_periods:
        if candidate_start + duration <= start:
            if not conflicts_with_downtime(machine, candidate_start,
                                          candidate_start + duration, downtimes):
                return candidate_start
        candidate_start = max(candidate_start, end)

    # Try at the end, skipping downtimes
    max_iter = 100
    iteration = 0
    while conflicts_with_downtime(machine, candidate_start,
                                  candidate_start + duration, downtimes):
        for dt in downtimes:
            if dt['machine'] == machine and dt['start'] <= candidate_start < dt['end']:
                candidate_start = dt['end']
                break
        iteration += 1
        if iteration > max_iter:
            break

    return candidate_start


def greedy_schedule(jobs: Dict, downtimes: List[Dict],
                   baseline_schedule: List[Dict] = None,
                   policy: Dict = None) -> List[Dict]:
    """
    Create a greedy schedule for job shop problem.
    """
    schedule = []
    machine_schedule = {}
    job_completion = {}

    # Extract frozen operations from baseline
    frozen_ops = {}
    if baseline_schedule and policy and policy.get('freeze', {}).get('enabled'):
        freeze_until = policy['freeze']['freeze_until']
        for op in baseline_schedule:
            if op['start'] < freeze_until:
                key = (op['job'], op['op'])
                frozen_ops[key] = op

    # Schedule each job's operations in order
    for job_id in sorted(jobs.keys()):
        prev_end = 0

        for op_idx, alternatives in enumerate(jobs[job_id]):
            key = (job_id, op_idx)

            # Check if this operation is frozen
            if key in frozen_ops:
                frozen_op = frozen_ops[key].copy()
                schedule.append(frozen_op)

                machine = frozen_op['machine']
                if machine not in machine_schedule:
                    machine_schedule[machine] = []
                machine_schedule[machine].append((frozen_op['start'], frozen_op['end']))

                prev_end = frozen_op['end']
                continue

            # Try each alternative and pick the one with earliest completion
            best_option = None
            best_end = float('inf')

            for machine, duration in alternatives:
                earliest = max(prev_end, earliest_available_time(
                    machine, duration, machine_schedule, downtimes, prev_end
                ))

                # Skip downtime windows
                max_iter = 100
                iteration = 0
                while conflicts_with_downtime(machine, earliest, earliest + duration, downtimes):
                    for dt in downtimes:
                        if dt['machine'] == machine and dt['start'] <= earliest < dt['end']:
                            earliest = dt['end']
                            break
                    iteration += 1
                    if iteration > max_iter:
                        break

                end_time = earliest + duration

                if end_time < best_end:
                    best_end = end_time
                    best_option = {
                        'job': job_id,
                        'op': op_idx,
                        'machine': machine,
                        'start': earliest,
                        'end': end_time,
                        'dur': duration
                    }

            if best_option:
                schedule.append(best_option)

                machine = best_option['machine']
                if machine not in machine_schedule:
                    machine_schedule[machine] = []
                machine_schedule[machine].append((best_option['start'], best_option['end']))

                prev_end = best_option['end']

    return schedule


def validate_schedule(schedule: List[Dict], downtimes: List[Dict]) -> Dict:
    """Perform comprehensive validation of a schedule."""
    errors = []

    # 1. Check machine conflicts
    machine_timeline = {}
    for op in schedule:
        machine = op['machine']
        start = op['start']
        end = op['end']

        if machine not in machine_timeline:
            machine_timeline[machine] = []

        for existing_start, existing_end, existing_op in machine_timeline[machine]:
            if start < existing_end and end > existing_start:
                errors.append(
                    f"Machine {machine} conflict: Job {op['job']} Op {op['op']} "
                    f"overlaps with Job {existing_op['job']} Op {existing_op['op']}"
                )

        machine_timeline[machine].append((start, end, op))

    # 2. Check precedence
    job_operations = {}
    for op in schedule:
        job_id = op['job']
        if job_id not in job_operations:
            job_operations[job_id] = []
        job_operations[job_id].append(op)

    for job_id, ops in job_operations.items():
        ops_sorted = sorted(ops, key=lambda x: x['op'])
        for i in range(len(ops_sorted) - 1):
            if ops_sorted[i]['end'] > ops_sorted[i + 1]['start']:
                errors.append(
                    f"Job {job_id}: Op {ops_sorted[i]['op']} ends at {ops_sorted[i]['end']} "
                    f"but Op {ops_sorted[i+1]['op']} starts at {ops_sorted[i+1]['start']}"
                )

    # 3. Check durations
    for op in schedule:
        expected_dur = op['end'] - op['start']
        if expected_dur != op['dur']:
            errors.append(
                f"Job {op['job']} Op {op['op']}: duration mismatch "
                f"(end-start={expected_dur}, dur={op['dur']})"
            )

    # 4. Check downtime violations
    violation_count = 0
    for op in schedule:
        machine = op['machine']
        start = op['start']
        end = op['end']

        for dt in downtimes:
            if dt['machine'] != machine:
                continue

            if start < dt['end'] and end > dt['start']:
                violation_count += 1
                errors.append(
                    f"Job {op['job']} Op {op['op']} on Machine {machine} "
                    f"[{start}, {end}) conflicts with downtime [{dt['start']}, {dt['end']})"
                )

    makespan = max(op['end'] for op in schedule) if schedule else 0

    return {
        'valid': len(errors) == 0,
        'errors': errors,
        'makespan': makespan,
        'downtime_violations': violation_count
    }


def validate_policy(schedule: List[Dict], policy: Dict,
                   baseline_schedule: List[Dict], baseline_makespan: int) -> Dict:
    """Validate policy constraints."""
    errors = []

    if not policy:
        return {'valid': True, 'errors': []}

    # 1. Check freeze policy
    if policy.get('freeze', {}).get('enabled', False):
        freeze_until = policy['freeze']['freeze_until']
        lock_fields = policy['freeze']['lock_fields']

        baseline_dict = {(op['job'], op['op']): op for op in baseline_schedule}

        for op in schedule:
            key = (op['job'], op['op'])
