                    for dt in downtimes:
                        if dt['machine'] == machine and dt['start'] <= earliest < dt['end']:
                            earliest = dt['end']
                            break
                    iteration += 1
                    if iteration > max_iter:
                        break

                end_time = earliest + duration

                if end_time < best_end:
