#!/usr/bin/env python3
"""
Production Scheduling Solver
Solves job shop scheduling with downtime and policy constraints.
"""

import json
import pandas as pd
from typing import Dict, List, Tuple


def parse_instance(filename: str) -> Dict[int, List[List[Tuple[int, int]]]]:
    """
    Parse JSSP instance file.
    Format:
    Line 1: num_jobs num_ops_per_job
    For each job:
      Line: num_ops
      For each operation:
        Line: num_alternatives machine1 duration1 machine2 duration2 ...

    Returns: jobs dictionary with structure:
    {
        job_id: [
            [(machine1, duration1), (machine2, duration2), ...],  # op 0 alternatives
            [(machine1, duration1), ...],  # op 1 alternatives
        ]
    }
    """
    jobs = {}
    with open(filename, 'r') as f:
        lines = [line.strip() for line in f.readlines() if line.strip()]

    # Parse first line: num_jobs num_ops_per_job
    first_line = lines[0].split()
    num_jobs = int(first_line[0])
    num_ops_per_job = int(first_line[1])

    line_idx = 1
    for job_id in range(num_jobs):
        # Read number of operations for this job
        num_ops = int(lines[line_idx])
        line_idx += 1

        job_operations = []

        # Read each operation
        for op_idx in range(num_ops):
            op_parts = lines[line_idx].split()
            line_idx += 1

            num_alternatives = int(op_parts[0])
            alternatives = []

            for alt_idx in range(num_alternatives):
                machine = int(op_parts[1 + alt_idx * 2])
                duration = int(op_parts[2 + alt_idx * 2])
                alternatives.append((machine, duration))

            job_operations.append(alternatives)

        jobs[job_id] = job_operations

    return jobs


def load_downtime_windows(filename: str) -> List[Dict]:
    """Load machine downtime windows from CSV."""
    df = pd.read_csv(filename)
    downtimes = []
    for _, row in df.iterrows():
        downtimes.append({
            'machine': int(row['machine']),
            'start': int(row['start']),
            'end': int(row['end']),
            'reason': row.get('reason', '')
        })
    return downtimes


def load_policy(filename: str) -> Dict:
    """Load policy constraints from JSON file."""
    with open(filename, 'r') as f:
        return json.load(f)


def load_baseline(filename: str) -> Dict:
    """Load baseline schedule from JSON file."""
    with open(filename, 'r') as f:
        return json.load(f)


def conflicts_with_downtime(machine: int, start: int, end: int, downtimes: List[Dict]) -> bool:
    """Check if an operation conflicts with any downtime window."""
    for dt in downtimes:
        if dt['machine'] != machine:
            continue
        if start < dt['end'] and end > dt['start']:
            return True
    return False


def earliest_available_time(machine: int, duration: int, machine_schedule: Dict,
                            downtimes: List[Dict], after: int = 0) -> int:
    """Find the earliest time a machine can start an operation of given duration."""
    # Get all busy periods and downtime periods for this machine
    busy_periods = sorted(machine_schedule.get(machine, []), key=lambda x: x[0])
    machine_downtimes = sorted([dt for dt in downtimes if dt['machine'] == machine],
                               key=lambda x: x['start'])

    # Merge all unavailable periods (busy + downtime)
    unavailable = []
    for start, end in busy_periods:
        unavailable.append((start, end))
    for dt in machine_downtimes:
        unavailable.append((dt['start'], dt['end']))

    unavailable.sort()

    # Merge overlapping unavailable periods
    merged = []
    for start, end in unavailable:
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))

    # Find earliest gap that fits the operation
    candidate_start = after

    for start, end in merged:
        if candidate_start + duration <= start:
            return candidate_start
        candidate_start = max(candidate_start, end)

    return candidate_start


def greedy_schedule(jobs: Dict, downtimes: List[Dict],
                   baseline_schedule: List[Dict] = None,
                   policy: Dict = None) -> List[Dict]:
    """
    Create a greedy schedule for job shop problem.
    """
    schedule = []
