    else:
        # Empty schedule
        df = pd.DataFrame(columns=['job', 'op', 'machine', 'start', 'end', 'dur'])
        df.to_csv('/app/output/schedule.csv', index=False)

    print(f"\nSolution written to /app/output/solution.json")
    print(f"Schedule written to /app/output/schedule.csv")
    print(f"Status: {status}")

    return solution


if __name__ == '__main__':
    main()

