#!/usr/bin/env python3
"""
Production Scheduling Solver V2
Uses priority dispatch scheduling for better parallelism.
"""

import json
import pandas as pd
from typing import Dict, List, Tuple
import heapq


def parse_instance(filename: str) -> Dict[int, List[List[Tuple[int, int]]]]:
    """Parse JSSP instance file."""
    jobs = {}
    with open(filename, 'r') as f:
        lines = [line.strip() for line in f.readlines() if line.strip()]

    first_line = lines[0].split()
    num_jobs = int(first_line[0])

    line_idx = 1
    for job_id in range(num_jobs):
        num_ops = int(lines[line_idx])
        line_idx += 1

        job_operations = []
        for op_idx in range(num_ops):
            op_parts = lines[line_idx].split()
            line_idx += 1

            num_alternatives = int(op_parts[0])
            alternatives = []

            for alt_idx in range(num_alternatives):
                machine = int(op_parts[1 + alt_idx * 2])
                duration = int(op_parts[2 + alt_idx * 2])
                alternatives.append((machine, duration))

            job_operations.append(alternatives)

        jobs[job_id] = job_operations

    return jobs


def load_downtime_windows(filename: str) -> List[Dict]:
    """Load machine downtime windows from CSV."""
    df = pd.read_csv(filename)
    downtimes = []
    for _, row in df.iterrows():
        downtimes.append({
            'machine': int(row['machine']),
            'start': int(row['start']),
            'end': int(row['end']),
            'reason': row.get('reason', '')
        })
    return downtimes


def load_policy(filename: str) -> Dict:
    """Load policy constraints from JSON file."""
    with open(filename, 'r') as f:
        return json.load(f)


def load_baseline(filename: str) -> Dict:
    """Load baseline schedule from JSON file."""
    with open(filename, 'r') as f:
        return json.load(f)


def earliest_available_time(machine: int, duration: int, machine_schedule: Dict,
                            downtimes: List[Dict], after: int = 0) -> int:
    """Find the earliest time a machine can start an operation."""
    busy_periods = sorted(machine_schedule.get(machine, []), key=lambda x: x[0])
    machine_downtimes = sorted([dt for dt in downtimes if dt['machine'] == machine],
                               key=lambda x: x['start'])

    # Merge all unavailable periods
    unavailable = []
    for start, end in busy_periods:
        unavailable.append((start, end))
    for dt in machine_downtimes:
        unavailable.append((dt['start'], dt['end']))

    unavailable.sort()

    # Merge overlapping periods
    merged = []
    for start, end in unavailable:
        if merged and start <= merged[-1][1]:
            merged[-1] = (merged[-1][0], max(merged[-1][1], end))
        else:
            merged.append((start, end))

    # Find earliest gap
    candidate_start = after

    for start, end in merged:
        if candidate_start + duration <= start:
            return candidate_start
        candidate_start = max(candidate_start, end)

    return candidate_start


def dispatch_schedule(jobs: Dict, downtimes: List[Dict],
                     baseline_schedule: List[Dict] = None) -> List[Dict]:
    """
    Create schedule using priority dispatching.
    All jobs are considered in parallel, operations scheduled as they become ready.
    """
    schedule = []
    machine_schedule = {}

    # Build baseline reference
    baseline_dict = {}
    if baseline_schedule:
        for op in baseline_schedule:
            key = (op['job'], op['op'])
            baseline_dict[key] = op

    # Track completion time of last operation for each job
    job_next_op = {job_id: 0 for job_id in jobs.keys()}
    job_last_end = {job_id: 0 for job_id in jobs.keys()}

    # Priority queue: (ready_time, job_id)
    # ready_time is when this job's next operation can start
    ready_queue = [(0, job_id) for job_id in jobs.keys()]
    heapq.heapify(ready_queue)

    completed_ops = 0
    total_ops = sum(len(ops) for ops in jobs.values())

    while completed_ops < total_ops:
        if not ready_queue:
            break

        ready_time, job_id = heapq.heappop(ready_queue)
        op_idx = job_next_op[job_id]

        if op_idx >= len(jobs[job_id]):
            continue

        alternatives = jobs[job_id][op_idx]
        key = (job_id, op_idx)

        # Find best machine for this operation
        best_option = None
        best_score = float('inf')
        baseline_machine = baseline_dict.get(key, {}).get('machine')

        for machine, duration in alternatives:
            earliest = earliest_available_time(
                machine, duration, machine_schedule, downtimes,
                job_last_end[job_id]
            )

            end_time = earliest + duration

            # Score: prioritize earlier completion, with bonus for baseline machine
            score = end_time
            if machine == baseline_machine:
                score -= 0.1  # Small bonus for matching baseline

            if score < best_score:
                best_score = score
                best_option = {
                    'job': job_id,
                    'op': op_idx,
                    'machine': machine,
                    'start': earliest,
                    'end': end_time,
                    'dur': duration
                }

        if best_option:
            schedule.append(best_option)

            # Update machine schedule
            machine = best_option['machine']
            if machine not in machine_schedule:
                machine_schedule[machine] = []
            machine_schedule[machine].append((best_option['start'], best_option['end']))

            # Update job tracking
            job_last_end[job_id] = best_option['end']
            job_next_op[job_id] += 1
            completed_ops += 1

            # Add job back to queue if it has more operations
            if job_next_op[job_id] < len(jobs[job_id]):
                heapq.heappush(ready_queue, (job_last_end[job_id], job_id))

    return schedule


def validate_schedule(schedule: List[Dict], downtimes: List[Dict]) -> Dict:
    """Perform comprehensive validation."""
    errors = []

    # 1. Check machine conflicts
    machine_timeline = {}
    for op in schedule:
        machine = op['machine']
        start = op['start']
        end = op['end']

        if machine not in machine_timeline:
            machine_timeline[machine] = []

        for existing_start, existing_end, existing_op in machine_timeline[machine]:
            if start < existing_end and end > existing_start:
                errors.append(f"Machine {machine} conflict")

        machine_timeline[machine].append((start, end, op))

    # 2. Check precedence
    job_operations = {}
    for op in schedule:
        job_id = op['job']
        if job_id not in job_operations:
            job_operations[job_id] = []
        job_operations[job_id].append(op)

    for job_id, ops in job_operations.items():
        ops_sorted = sorted(ops, key=lambda x: x['op'])
        for i in range(len(ops_sorted) - 1):
            if ops_sorted[i]['end'] > ops_sorted[i + 1]['start']:
                errors.append(f"Job {job_id} precedence violation")

    # 3. Check durations
    for op in schedule:
        if op['end'] - op['start'] != op['dur']:
            errors.append(f"Job {op['job']} Op {op['op']} duration mismatch")

    # 4. Check downtime violations
    violation_count = 0
    for op in schedule:
        for dt in downtimes:
            if dt['machine'] == op['machine']:
                if op['start'] < dt['end'] and op['end'] > dt['start']:
                    violation_count += 1

    makespan = max(op['end'] for op in schedule) if schedule else 0

    return {
        'valid': len(errors) == 0,
        'errors': errors,
        'makespan': makespan,
        'downtime_violations': violation_count
    }


def validate_policy(schedule: List[Dict], policy: Dict,
                   baseline_schedule: List[Dict], baseline_makespan: int) -> Dict:
    """Validate policy constraints."""
    errors = []

    if not policy:
        return {'valid': True, 'errors': []}

    baseline_dict = {(op['job'], op['op']): op for op in baseline_schedule}

    # Check change budget
    if 'change_budget' in policy:
        machine_changes = 0
        total_start_shift = 0

        for op in schedule:
            key = (op['job'], op['op'])
            if key in baseline_dict:
                baseline_op = baseline_dict[key]
                if op['machine'] != baseline_op['machine']:
                    machine_changes += 1
                total_start_shift += abs(op['start'] - baseline_op['start'])

        max_machine_changes = policy['change_budget'].get('max_machine_changes', float('inf'))
        max_start_shift = policy['change_budget'].get('max_total_start_shift_L1', float('inf'))

        if machine_changes > max_machine_changes:
            errors.append(f"Machine changes: {machine_changes} > {max_machine_changes}")

        if total_start_shift > max_start_shift:
            errors.append(f"Start shift: {total_start_shift} > {max_start_shift}")

    # Check makespan guard
    if 'guards' in policy:
        makespan = max(op['end'] for op in schedule) if schedule else 0
        max_ratio = policy['guards'].get('max_makespan_ratio', float('inf'))

        if makespan > baseline_makespan * max_ratio:
            errors.append(f"Makespan: {makespan} > {baseline_makespan * max_ratio}")

    return {
        'valid': len(errors) == 0,
        'errors': errors
    }


def main():
    """Main solver function."""
    print("Loading input data...")
    jobs = parse_instance('/app/data/instance.txt')
    downtimes = load_downtime_windows('/app/data/downtime.csv')
    policy = load_policy('/app/data/policy.json')
    baseline = load_baseline('/app/data/baseline_solution.json')

    print(f"Loaded {len(jobs)} jobs")
    print(f"Loaded {len(downtimes)} downtime windows")
    print(f"Baseline makespan: {baseline['makespan']}")

    # Create schedule
    print("\nGenerating schedule with dispatch algorithm...")
    schedule = dispatch_schedule(jobs, downtimes, baseline['schedule'])

    # Validate
    print("\nValidating schedule...")
    validation = validate_schedule(schedule, downtimes)

    if not validation['valid']:
        print("Schedule validation failed:")
        for error in validation['errors']:
            print(f"  - {error}")
    else:
        print("Schedule is valid!")

    print(f"Makespan: {validation['makespan']} (baseline: {baseline['makespan']})")
    print(f"Downtime violations: {validation['downtime_violations']}")

    # Validate policy
    policy_validation = validate_policy(
        schedule, policy, baseline['schedule'], baseline['makespan']
    )

    if not policy_validation['valid']:
        print("\nPolicy validation:")
        for error in policy_validation['errors']:
            print(f"  - {error}")
    else:
        print("Policy constraints satisfied!")

    # Determine status
    if validation['valid'] and policy_validation['valid'] and validation['downtime_violations'] == 0:
        status = "OPTIMAL"
    elif validation['valid'] and validation['downtime_violations'] == 0:
        status = "FEASIBLE"
    else:
        status = "INFEASIBLE"

    # Create solution
    solution = {
        "status": status,
        "makespan": validation['makespan'],
        "schedule": sorted(schedule, key=lambda x: (x['start'], x['job'], x['op']))
    }

    # Write outputs
    import os
    os.makedirs('/app/output', exist_ok=True)

    with open('/app/output/solution.json', 'w') as f:
        json.dump(solution, f, indent=2)

    if solution['schedule']:
        df = pd.DataFrame(solution['schedule'])
        columns = ['job', 'op', 'machine', 'start', 'end', 'dur']
        df = df[columns]
        df.to_csv('/app/output/schedule.csv', index=False)

    print(f"\nSolution written to /app/output/solution.json")
    print(f"Schedule written to /app/output/schedule.csv")
    print(f"Status: {status}")

    return solution


if __name__ == '__main__':
    main()

